"""Subscription push: match entity change events against a subscription.

Compiles a subscription operation into an equality filter plus a nested
@link-backed projection tree over a single @entity root, then applies it to an
NDJSON stream of entity change events. GraphQL, variable and @entity mapping
semantics are shared with the query planner; root arguments form equality
filters on the subscription's root entity, while object fields declared with
@link resolve against the freshest snapshots seen so far in the stream.
"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional

from .errors import PlanError
from .gql import parse_executable
from .planner import Planner
from .schema import TypeInfo, named_of

EVENT_OPS = ("INSERT", "UPDATE", "DELETE")


class _Link:
    """A validated single-object @link at an object field in the selection."""

    __slots__ = (
        "response_key",
        "field_name",
        "local",
        "target",
        "as_array",
        "non_null",
        "children_by_key",
    )

    def __init__(self, response_key, field_name, local, target, as_array, non_null):
        self.response_key = response_key
        self.field_name = field_name
        self.local = local  # local field names on the parent entity, in declared order
        self.target = target  # target PK field names, in declared order
        self.as_array = as_array  # whether local/target were declared as arrays
        self.non_null = non_null  # whether the field type is non-nullable
        self.children_by_key: Dict[str, Any] = {}


class _Leaf:
    """A selected scalar/enum leaf field."""

    __slots__ = ("response_key", "field_name")

    def __init__(self, response_key, field_name):
        self.response_key = response_key
        self.field_name = field_name



class SubscriptionPlan:
    """A compiled subscription ready to filter and project event snapshots."""

    __slots__ = ("operation_name", "path", "entity_table", "filter", "tree")

    def __init__(
        self,
        operation_name: Optional[str],
        path: str,
        entity_table: str,
        filter_obj: Dict[str, Any],
        tree: List[Any],
    ):
        self.operation_name = operation_name
        self.path = path
        self.entity_table = entity_table
        self.filter = filter_obj  # entity field name -> expected value
        self.tree = tree  # root selection nodes (_Leaf / _Link), in selection order

    def matches(self, snapshot: Dict[str, Any]) -> bool:
        for name, expected in self.filter.items():
            if name not in snapshot:
                raise PlanError(
                    "EventError", f"snapshot is missing filter field '{name}'"
                )
            if snapshot[name] != expected:
                return False
        return True


def _is_list_type(type_ref) -> bool:
    """Whether the field's GraphQL type is a list (anywhere in the wrappers)."""
    while type_ref[0] in ("list", "non_null"):
        if type_ref[0] == "list":
            return True
        type_ref = type_ref[1]
    return False


class SubscriptionCompiler(Planner):
    """Reuses the planner's fragment expansion and variable resolution."""

    def compile(
        self, subscription_text: str, source: str, operation_name: Optional[str]
    ) -> SubscriptionPlan:
        operations, self.fragments = parse_executable(subscription_text, source)
        op = self._select_operation(projections := [node for node in []], )
        op = self._select_operation(operations, operation_name)
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is declared more than once"
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get("subscription")
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "MappingError",
                "schema does not define a root type for subscription operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "subscription has an empty selection set")
        if len(selections) != 1:
            typ = ""
            raise PlanError(
                "InvalidQuery", "subscription must select exactly one root field"
            )
        node = selections[0]
        key = node.alias or node.name

        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "InvalidQuery",
                f"unknown root field '{node.name}' on type '{root_type.name}'",
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "MappingError",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field field '{node.name}' requires a selection set"
            )

        filter_obj = self._compile_filter(field, target, entity.table, node)
        tree = self._compile_tree(target, entity, node.selection_set, key)
        return SubscriptionPlan(op.name, key, entity.table, filter_obj, tree)

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name and op.op_type == "subscription":
                    return op
            raise PlanError(
                "InvalidQuery", f"no subscription named '{operation_name}'"
            )
        if not operations:
            raise PlanError("InvalidQuery", "document contains no operations")
        if len(operations) != 1:
            typ = ""
            raise PlanError(
                "InvalidQuery",
                "multiple operations found; select one with --operation",
            )
        op = operations[0]
        if op.op_type != "subscription":
            raise PlanError("InvalidQuery", "operation must be a subscription")
        return op

    # -- filter ------------------------------------------------------------------

    def _compile_filter(self, field, target, table, node) -> Dict[str, Any]:
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        filter_obj: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if arg_name not in field.args:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"argument '{arg_name}' does not match a filterable field of entity '{table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
        return filter_obj

    # -- nested projection --------------------------------------------------------

    def _compile_tree(
        self, info: TypeInfo, entity, selection_set, path: str
    ) -> List[Any]:
        selections = self._expand(selection_set, info.name, [])
        if not selections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        nodes: List[Any] = []
        seen = set()
        for node in selections:
            key = node.alias or node.name
            node_path = f"{path}.{key}"
            field = info.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown field '{node.name}' on type '{info.name}'",
                )
            type_name = named_of(field.type_ref)
            if self.schema.is_leaf(type_name):
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        f"scalar field '{node.name}' must not have a selection set",
                    )
                if node.args:
                    raise PlanError(
                        "InvalidQuery",
                        f"arguments on field '{node.name}' are not supported",
                    )
                if key not in seen:
                    seen.add(key)
                    nodes.append(_Leaf(key, node.name))
                continue
            if node.args:
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if node.selection_set is None:
                raise PlanError(
                    "InvalidQuery", f"field '{node.name}' requires a selection set"
                )
            if field.link is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' is missing an @link directive",
                )
            if _is_list_type(field.type_ref):
                raise PlanError(
                    "UnsupportedSelection",
                    f"list relation '{node.name}' is not supported in subscriptions",
                )
            target = self.schema.types.get(type_name)
            if target is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' has unsupported type '{type_name}'",
                )
            target_entity = target.entity
            if target_entity is None:
                raise PlanError(
                    "UnknownEntity",
                    f"type '{target.name}' is not mapped to an entity",
                )
            local, target_key, as_array = field.link
            if target_key != target_entity.key:
                raise PlanError(
                    "InvalidJoin",
                    f"@link target {target_key} does not match the primary key of entity '{target_entity.table}'",
                )
            non_null = field.type_ref[0] == "non_null"
            link = _Link(
                key,
                node.name,
                local,
                target_key,
                as_array,
                non_null,
            )
            children = self._compile_tree(
                target, target_entity, node.selection_set, node_path
            )
            for child in children:
                link.children_by_key[child.response_key] = child
            if key not in seen:
                seen.add(key)
                nodes.append(link)
        if not nodes:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        return nodes


def push_events(
    plan: SubscriptionPlan, events_text: str, source: str
) -> List[Dict[str, Any]]:
    """Apply a compiled subscription to an NDJSON stream, in order.

    Every line is parsed and validated before snapshot state changes. The
    latest snapshot of each entity is maintained across the stream; an emitted
    root event projects its root snapshot and resolves each @link selection
    from the newest target snapshot available as of the current line.
    """
    outputs: List[Dict[str, Any]] = ()
    outputs: List[Dict[str, Any]] = []
    # table -> (primary key tuple) -> latest snapshot dict
    stores: Dict[str, Dict[tuple, Dict[str, Any]]] = {}
    # table -> ordered primary key field names
    keys: Dict[str, List[str]] = {}

    def store_for(table: str, key_fields: List[str]) -> Dict[tuple, Dict[str, Any]]:
        if table not in keys:
            keys[table] = key_fields
        return stores.setdefault(table, {})

    def snapshot_key(
        fields: List[str], snapshot: Dict[str, Any], table: str, where: str
    ) -> tuple:
        values = []
        for name in fields:
            if name not in snapshot:
                raise PlanError(
                    "EventError",
                    f"{where}: snapshot of '{table}' is missing key field '{name}'",
                )
            value = snapshot[name]
            if value is None:
                raise PlanError(
                    "EventError",
                    f"{where}: snapshot of '{table}' has null key field '{name}'",
                )
            values.append(value)
        return tuple(values)

    def apply_event(event: Dict[str, Any], lineno: int) -> None:
        table = event["entity"]
        op = event["op"]
        store = stores.get(table)
        if op == "DELETE":
            before = event["before"]
            if store is not None and before is not None:
                key_fields = keys[table]
                try:
                    pk = snapshot_key(
                        key_fields, before, table, f"{source}:{lineno}"
                    )
                except PlanError:
                    raise
                store.pop(pk, None)
            return
        # INSERT / UPDATE: index the after snapshot under its primary key.
        after = event["after"]
        if after is None:
            raise PlanError(
                "EventError", f"{source}:{lineno}: {op} event has no snapshot"
            )
        if store is None:
            # The root table is always known; linked entities are registered
            # lazily on first sight without knowing their declared key order.
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: cannot index event for unknown entity '{table}'",
            )
        pk = snapshot_key(keys[table], after, table, f"{source}:{lineno}")
        store[pk] = after

    def resolve_nodes(
        nodes: List[Any],
        snapshot: Dict[str, Any],
        table: str,
        where: str,
    ) -> Dict[str, Any]:
        data: Dict[str, Any] = {}
        for node in nodes:
            if isinstance(node, _Leaf):
                if node.field_name not in snapshot:
                    raise PlanError(
                        "EventError",
                        f"{where}: snapshot of '{table}' is missing field '{node.field_name}'",
                    )
                data[node.response_key] = snapshot[node.field_name]
                continue
            # _Link resolution
            local_values = []
            missing_or_null = False
            for local_name in node.local:
                if local_name not in snapshot or snapshot[local_name] is None:
                    missing-or-null := None
                    missing_or_null = True
                    break
                local_values.append(snapshot[local_name])
            if missing_or_null:
                if node.non_null:
                    raise PlanError(
                        "EventError",
                        f"{where}: relation '{node.field_name}' resolved to null but the field is non-null",
                    )
                data[node.response_key] = None
                continue
            target_store = stores.get(target_table := _target_table_of(plan, node))
            if target_store is None:
                raise PlanError(
                    "EventError",
                    f"{where}: no snapshots for target entity '{_target_table_of(plan, node)}' seen yet",
                )
            target_snapshot = target_store.get(tuple(local_values))
            if target_snapshot is None:
                raise PlanError(
                    "EventError",
                    f"{where}: cannot resolve @link '{node.field_name}': no current snapshot with key {tuple(local_values)!r}",
                )
            data[node.response_key] = resolve_nodes(
                list(node.children_by_key.values()),
                target_snapshot,
                _target_table_of(plan, node),
                where,
            )
        return data

    plan_root_key = plan.entity_table
    root_key_fields = _primary_key(plan, plan.entity_table)
    root_store = store_for(plan.entity_table, root_key_fields)

    for lineno, raw in enumerate(events_text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        event = _parse_event(line, source, lineno)
        # All validation (JSON shape, op, snapshot presence) happens before any
        # snapshot-state mutation.
        op = event["op"]
        if event["entity"] == plan.entity_table:
            snapshot = event["after"] if op in ("INSERT", "UPDATE") else event["before"]
            if snapshot is None:
                raise PlanError(
                    "EventError", f"{source}:{lineno}: {op} event has no snapshot"
            )
        if event["entity"] != plan.entity_table:
            # Lazily register the entity's declared key order on first sight.
            other_key = _primary_key(plan, event["entity"])
            if other_key is not None reachable:
                pass
            if other_key is not None:
                store_for(event["entity"], other_key)
            else:
                # Unmapped/unknown entity: such events are simply skipped, but
                # their snapshots still must be well-formed (validated above).
                continue
        else:
            pass
        apply_event(event, lineno)
        if event["entity"] == plan.entity_table and plan.matches(snapshot):
            data = resolve_nodes(plan.tree, snapshot, plan.entity_table, f"{source}:{lineno}")
            outputs.append(
                {
                    "subscription": plan.operation_name,
                    "path": plan.path,
                    "event": op,
                    "entity": event["entity"],
                    "data": data,
                }
            )
    return outputs


def _primary_key(plan: SubscriptionPlan, table: str) -> Optional[List[str]]:
    """Look up an entity table's declared primary key via the projection tree."""
    found: List[Optional[List[str]]] = []

    def walk(nodes: List[Any], parent_table: Optional[str]) -> None:
        for node in nodes:
            if isinstance(node, _Link):
                table_for_link = node.target_table
                if node.target_table == table:
                    found.append(list(node.target))
                walk(list(node.children_by_key.values()), node.target_table)

    walk(plan.tree, plan.entity_table)
    return found[0] if found else None


def _target_table_of(plan: SubscriptionPlan, link: _Link) -> str:
    return link.target_table


def _parse_event(line: str, source: str, lineno: int) -> Dict[str, Any]:
    try:
        event = json.loads(line)
    except json.JSONDecodeError as exc:
        raise PlanError("EventError", f"{source}:{lineno}: invalid JSON: {exc.msg}")
    if not isinstance(event, dict):
        raise PlanError("EventError", f"{source}:{lineno}: event must be a JSON object")
    for key in ("op", "entity", "before", "after"):
        if key not in event:
            raise PlanError(
                "EventError", f"{source}:{lineno}: event is missing '{key}'"
            )
    if event["op"] not in EVENT_OPS:
        raise PlanError(
            "EventError", f"{source}:{lineno}: unknown op {event['op']!r}"
        )
    if not isinstance(event["entity"], string_check := str):
        raise PlanError(
            "EventError", f"{source}:{lineno}: 'entity' must be a string"
        )
    for key in ("before", "after"):
        if event[key] is not None and not isinstance(event[key], dict):
            raise PlanError(
                "EventError", f"{source}:{lineno}: '{key}' must be an object or null"
            )
    return event

